content:
:root {
  --bg-primary: #f8fafc;
  --bg-card: #ffffff;
  --bg-subtle: #f1f5f9;
  --border-color: #e2e8f0;
  --border-light: #edf2f7;

  --text-primary: #0f172a;
  --text-secondary: #475569;
  --text-muted: #64748b;
  --text-light: #94a3b8;

  --primary: #3b82f6;
  --primary-hover: #2563eb;
  --primary-bg: #eff6ff;

  --success: #10b981;
  --success-bg: #ecfdf5;
  --danger: #ef4444;
  --danger-bg: #fef2f2;

  --accent-sales: #3b82f6;
  --accent-customers: #10b981;
  --accent-spend: #f59e0b;
  --accent-target: #8b5cf6;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --radius-full: 9999px;

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* ==========================================================================
   Dashboard Container & Layout
   ========================================================================== */

.dashboard-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 24px 20px 48px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* Header */
.dashboard-header {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding-bottom: 8px;
}

@media (min-width: 640px) {
  .dashboard-header {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.header-title-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.dashboard-title {
  font-size: 1.625rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.dashboard-subtitle {
  font-size: 0.875rem;
  color: var(--text-muted);
}

.header-controls {
  display: flex;
  align-items: center;
  gap: 12px;
}

/* Period Switcher Buttons */
.period-btn-group {
  display: inline-flex;
  padding: 3px;
  background-color: var(--bg-subtle);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
}

.period-btn {
  border: none;
  background: transparent;
  padding: 6px 14px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s ease-in-out;
  touch-action: manipulation;
}

.period-btn:hover {
  color: var(--text-primary);
}

.period-btn-active {
  background-color: var(--bg-card);
  color: var(--primary);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

/* ==========================================================================
   KPI Cards Section
   ========================================================================== */

.kpi-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

@media (min-width: 640px) {
  .kpi-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .kpi-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.kpi-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 14px;
  transition: box-shadow 0.2s ease, border-color 0.2s ease;
}

.kpi-card:hover {
  box-shadow: var(--shadow-md);
  border-color: #cbd5e1;
}

.kpi-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.kpi-card-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.kpi-icon-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: var(--radius-md);
  background-color: var(--bg-subtle);
  color: var(--text-secondary);
}

.kpi-card-value-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.kpi-card-value {
  font-size: 1.875rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: var(--text-primary);
  font-family: var(--font-mono);
}

.kpi-card-unit {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-muted);
}

.kpi-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8125rem;
  padding-top: 10px;
  border-top: 1px dashed var(--border-light);
}

.badge-positive {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  background-color: var(--success-bg);
  color: var(--success);
  font-weight: 600;
  font-size: 0.75rem;
}

.badge-negative {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  background-color: var(--danger-bg);
  color: var(--danger);
  font-weight: 600;
  font-size: 0.75rem;
}

.kpi-target-text {
  color: var(--text-muted);
  font-size: 0.75rem;
}

/* ==========================================================================
   Chart Section
   ========================================================================== */

.charts-section {
  display: flex;
  flex-direction: column;
}

.chart-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.chart-header {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

@media (min-width: 640px) {
  .chart-header {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.chart-title {
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--text-primary);
}

.chart-legend-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.metric-pill {
  border: 1px solid var(--border-color);
  background-color: var(--bg-card);
  color: var(--text-secondary);
  padding: 4px 12px;
  border-radius: var(--radius-full);
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s ease-in-out;
  touch-action: manipulation;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.metric-pill:hover {
  background-color: var(--bg-subtle);
  color: var(--text-primary);
}

.metric-pill-active {
  background-color: var(--primary-bg);
  border-color: var(--primary);
  color: var(--primary);
  font-weight: 600;
}

.chart-wrapper {
  width: 100%;
  height: 340px;
  position: relative;
}

@media (min-width: 640px) {
  .chart-wrapper {
    height: 380px;
  }
}

/* Recharts Custom Tooltip Styling */
.custom-tooltip {
  background-color: rgba(255, 255, 255, 0.95);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 10px 14px;
  box-shadow: var(--shadow-md);
  backdrop-filter: blur(4px);
  font-size: 0.8125rem;
}

.custom-tooltip-title {
  font-weight: 600;
  margin-bottom: 6px;
  color: var(--text-primary);
  border-bottom: 1px solid var(--border-light);
  padding-bottom: 4px;
}

.custom-tooltip-item {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  margin-top: 4px;
}

/* ==========================================================================
   Data Table Section
   ========================================================================== */

.table-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.table-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.table-title {
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--text-primary);
}

.table-wrapper {
  width: 100%;
  overflow-x: auto;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  -webkit-overflow-scrolling: touch;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.875rem;
  white-space: nowrap;
}

.th-cell {
  background-color: var(--bg-subtle);
  color: var(--text-secondary);
  font-weight: 600;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border-color);
  font-size: 0.8125rem;
}

.td-cell {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-light);
  color: var(--text-primary);
}

.data-table tbody tr:last-child .td-cell {
  border-bottom: none;
}

.data-table tbody tr:hover {
  background-color: #f8fafc;
}

.td-num {
  text-align: right;
  font-family: var(--font-mono);
}

.text-up {
  color: var(--success);
  font-weight: 600;
}

.text-down {
  color: var(--danger);
  font-weight: 600;
}

export interface MonthlySalesData {
