  sales: number;
  customers: number;
  avgSpend: number;
  targetSales: number;
}

export interface KpiSummaryItem {
  id: string;
  title: string;
  value: string;
  subValue: string;
  changeRate: number;
  isPositive: boolean;
  unit: string;
}

export type ChartMetricOption = 'all' | 'sales' | 'customers' | 'avgSpend';

export type PeriodType = '6months' | '12months';

