export const calculateKpiSummary = (data: MonthlySalesData[] = []): KpiSummaryItem[] => {
  if (data.length === 0) {
    return [
      { id: 'sales', title: '総売上高', value: '¥0', subValue: '目標比: 0.0%', changeRate: 0, isPositive: true, unit: '円' },
      { id: 'customers', title: '延べ客数', value: '0', subValue: '月平均: 0人', changeRate: 0, isPositive: true, unit: '人' },
      { id: 'avgSpend', title: '平均客単価', value: '¥0', subValue: '直近: ¥0', changeRate: 0, isPositive: true, unit: '円' },
    ];
  }

  const currentMonth = data[data.length - 1];
  const prevMonth = data.length > 1 ? data[data.length - 2] : null;

  const totalSales = data.reduce((sum, item) => sum + item.sales, 0);
  const totalTargetSales = data.reduce((sum, item) => sum + item.targetSales, 0);
  const targetRate = totalTargetSales > 0 ? (totalSales / totalTargetSales) * 100 : 0;
  const salesChangeRate = prevMonth && prevMonth.sales > 0
    ? ((currentMonth.sales - prevMonth.sales) / prevMonth.sales) * 100
    : 0;

  const totalCustomers = data.reduce((sum, item) => sum + item.customers, 0);
  const avgCustomers = Math.round(totalCustomers / data.length);
  const customerChangeRate = prevMonth && prevMonth.customers > 0
    ? ((currentMonth.customers - prevMonth.customers) / prevMonth.customers) * 100
    : 0;

  const overallAvgSpend = totalCustomers > 0 ? Math.round(totalSales / totalCustomers) : 0;
  const spendChangeRate = prevMonth && prevMonth.avgSpend > 0
    ? ((currentMonth.avgSpend - prevMonth.avgSpend) / prevMonth.avgSpend) * 100
    : 0;

  return [
    {
      id: 'sales',
      title: '期間合計売上高',
      value: `¥${totalSales.toLocaleString()}`,
      subValue: `目標達成率: ${targetRate.toFixed(1)}%`,
      changeRate: parseFloat(salesChangeRate.toFixed(1)),
      isPositive: salesChangeRate >= 0,
      unit: '円',
    },
    {
      id: 'customers',
      title: '期間延べ来客数',
      value: totalCustomers.toLocaleString(),
      subValue: `月平均客数: ${avgCustomers.toLocaleString()}人`,
      changeRate: parseFloat(customerChangeRate.toFixed(1)),
      isPositive: customerChangeRate >= 0,
      unit: '人',
    },
    {
      id: 'avgSpend',
      title: '期間平均客単価',
      value: `¥${overallAvgSpend.toLocaleString()}`,
      subValue: `直近月単価: ¥${currentMonth.avgSpend.toLocaleString()}`,
      changeRate: parseFloat(spendChangeRate.toFixed(1)),
      isPositive: spendChangeRate >= 0,
      unit: '円',
    },
  ];
};

import { useMemo } from 'react';
import { DollarSign, Users, ShoppingBag, ArrowUpRight, ArrowDownRight } from 'lucide-react';
import { MonthlySalesData, KpiSummaryItem } from '../types';
import { calculateKpiSummary } from '../mockData';

interface KpiCardsProps {
  data?: MonthlySalesData[];
}

const getKpiIcon = (id: string) => {
  switch (id) {
    case 'sales':
      return <DollarSign size={20} strokeWidth={2.2} />;
    case 'customers':
      return <Users size={20} strokeWidth={2.2} />;
    case 'avgSpend':
      return <ShoppingBag size={20} strokeWidth={2.2} />;
    default:
      return <DollarSign size={20} strokeWidth={2.2} />;
  }
};

const KpiCards = ({ data = [] }: KpiCardsProps) => {
  const kpiItems: KpiSummaryItem[] = useMemo(() => {
    return calculateKpiSummary(data);
  }, [data]);

  return (
    <div className="kpi-grid">
      {kpiItems.map((kpi) => {
        const isPositive = kpi.isPositive;
        const changeRateDisplay = `${isPositive ? '+' : ''}${kpi.changeRate}%`;

        return (
          <div key={kpi.id} className="kpi-card">
            <div className="kpi-card-header">
              <span className="kpi-card-title">{kpi.title}</span>
              <div className="kpi-icon-badge">{getKpiIcon(kpi.id)}</div>
            </div>

            <div className="kpi-card-value-row">
              <span className="kpi-card-value">{kpi.value}</span>
              <span className="kpi-card-unit">{kpi.unit}</span>
            </div>

            <div className="kpi-card-footer">
              <div className={isPositive ? 'badge-positive' : 'badge-negative'}>
                {isPositive ? <ArrowUpRight size={14} /> : <ArrowDownRight size={14} />}
                <span>前月比 {changeRateDisplay}</span>
              </div>
              <span className="kpi-target-text">{kpi.subValue}</span>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default KpiCards;

import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { MonthlySalesData, ChartMetricOption } from '../types';

interface ChartSectionProps {
  data?: MonthlySalesData[];
  activeMetric?: ChartMetricOption;
  onMetricChange?: (metric: ChartMetricOption) => void;
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    name: string;
    value: number;
    color: string;
    dataKey: string;
  }>;
  label?: string;
}

const CustomTooltip = ({ active, payload, label }: CustomTooltipProps) => {
  if (!active || !payload || payload.length === 0) {
    return null;
  }

  return (
    <div className="custom-tooltip">
      <div className="custom-tooltip-title">{label} 実績</div>
      {payload.map((item, index) => {
        let formattedValue = item.value?.toLocaleString() ?? '0';
        if (item.dataKey === 'sales' || item.dataKey === 'targetSales') {
          formattedValue = `¥${formattedValue}`;
        } else if (item.dataKey === 'avgSpend') {
          formattedValue = `¥${formattedValue}`;
        } else if (item.dataKey === 'customers') {
          formattedValue = `${formattedValue} 人`;
        }

        return (
          <div key={`tooltip-${index}`} className="custom-tooltip-item">
            <span style={{ color: item.color, fontWeight: 500 }}>{item.name}:</span>
            <span style={{ fontWeight: 600, fontFamily: 'var(--font-mono)' }}>{formattedValue}</span>
          </div>
        );
      })}
    </div>
  );
};

const ChartSection = ({
  data = [],
  activeMetric = 'all',
  onMetricChange,
}: ChartSectionProps) => {
  const metricOptions: { id: ChartMetricOption; label: string }[] = [
    { id: 'all', label: '全体（売上・客数・単価）' },
    { id: 'sales', label: '売上・目標' },
    { id: 'customers', label: '来客数' },
    { id: 'avgSpend', label: '客単価' },
  ];

  const showSales = activeMetric === 'all' || activeMetric === 'sales';
  const showCustomers = activeMetric === 'all' || activeMetric === 'customers';
  const showSpend = activeMetric === 'all' || activeMetric === 'avgSpend';

  const formatSalesYAxis = (val: number) => {
    return `¥${(val / 10000).toFixed(0)}万`;
  };

  const formatSubYAxis = (val: number) => {
    if (activeMetric === 'customers') {
      return `${val}人`;
    }
    if (activeMetric === 'avgSpend') {
      return `¥${val}`;
    }
    return `${val}`;
  };

  return (
    <section className="charts-section">
      <div className="chart-card">
        <div className="chart-header">
          <h2 className="chart-title">月次実績推移チャート</h2>
          <div className="chart-legend-controls">
            {metricOptions.map((opt) => (
              <button
                key={opt.id}
                type="button"
                className={activeMetric === opt.id ? 'metric-pill metric-pill-active' : 'metric-pill'}
                onClick={() => onMetricChange?.(opt.id)}
              >
                {opt.label}
              </button>
            ))}
          </div>
        </div>

        <div className="chart-wrapper">
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart
              data={data}
              margin={{ top: 16, right: showCustomers || showSpend ? 20 : 10, left: 10, bottom: 0 }}
            >
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis
                dataKey="month"
                stroke="#64748b"
                tick={{ fontSize: 12 }}
                tickLine={false}
              />

              {/* Primary Y Axis (Sales) */}
              <YAxis
                yAxisId="salesAxis"
                stroke="#64748b"
                tick={{ fontSize: 11 }}
                tickLine={false}
                axisLine={false}
                tickFormatter={formatSalesYAxis}
                hide={!showSales}
              />

              {/* Secondary Y Axis (Customers / Spend) */}
              <YAxis
                yAxisId="subAxis"
                orientation="right"
                stroke="#64748b"
                tick={{ fontSize: 11 }}
                tickLine={false}
                axisLine={false}
                tickFormatter={formatSubYAxis}
                hide={!showCustomers && !showSpend}
              />

              <Tooltip content={<CustomTooltip />} />
              <Legend
                verticalAlign="bottom"
                height={36}
                iconType="circle"
                wrapperStyle={{ fontSize: '0.8125rem', paddingTop: '10px' }}
              />

              {/* Sales Target Line */}
              {showSales && (
                <Line
                  yAxisId="salesAxis"
                  type="monotone"
                  dataKey="targetSales"
                  name="目標売上"
                  stroke="#8b5cf6"
                  strokeWidth={2}
                  strokeDasharray="4 4"
                  dot={false}
                />
              )}

              {/* Sales Bar */}
              {showSales && (
                <Bar
                  yAxisId="salesAxis"
                  dataKey="sales"
                  name="売上高"
                  fill="#3b82f6"
                  radius={[4, 4, 0, 0]}
                  maxBarSize={48}
                />
              )}

              {/* Customer Count Line */}
              {showCustomers && (
                <Line
                  yAxisId="subAxis"
                  type="monotone"
                  dataKey="customers"
                  name="来客数(人)"
                  stroke="#10b981"
                  strokeWidth={2.5}
                  dot={{ r: 3, fill: '#10b981' }}
                  activeDot={{ r: 5 }}
                />
              )}

              {/* Average Spend Line */}
              {showSpend && (
                <Line
                  yAxisId="subAxis"
                  type="monotone"
                  dataKey="avgSpend"
                  name="客単価(円)"
                  stroke="#f59e0b"
                  strokeWidth={2.5}
                  dot={{ r: 3, fill: '#f59e0b' }}
                  activeDot={{ r: 5 }}
                />
              )}
            </ComposedChart>
          </ResponsiveContainer>
        </div>
      </div>
    </section>
  );
};

export default ChartSection;

import { useState, useMemo } from 'react';
import { PeriodType, ChartMetricOption } from './types';
import { getFilteredSalesData } from './mockData';
import KpiCards from './components/KpiCards';
import ChartSection from './components/ChartSection';

const App = () => {
  const [period, setPeriod] = useState<PeriodType>('12months');
  const [activeMetric, setActiveMetric] = useState<ChartMetricOption>('all');

  const filteredData = useMemo(() => {
    return getFilteredSalesData(period);
  }, [period]);

  const handlePeriodChange = (newPeriod: PeriodType) => {
    setPeriod(newPeriod);
  };

  const handleMetricChange = (metric: ChartMetricOption) => {
    setActiveMetric(metric);
  };

  return (
    <main className="dashboard-container">
      {/* Header */}
      <header className="dashboard-header">
        <div className="header-title-group">
          <h1 className="dashboard-title">店舗売上・経営分析ダッシュボード</h1>
          <p className="dashboard-subtitle">
            売上実績、客数推移、客単価および予算達成状況の集計レポート
          </p>
        </div>

        <div className="header-controls">
          <div className="period-btn-group" role="group" aria-label="集計期間の切り替え">
            <button
              type="button"
              className={period === '6months' ? 'period-btn period-btn-active' : 'period-btn'}
              onClick={() => handlePeriodChange('6months')}
            >
              直近6ヶ月
            </button>
            <button
              type="button"
              className={period === '12months' ? 'period-btn period-btn-active' : 'period-btn'}
              onClick={() => handlePeriodChange('12months')}
            >
              通年12ヶ月
            </button>
          </div>
        </div>
      </header>

      {/* KPI Cards */}
      <KpiCards data={filteredData} />

      {/* Monthly Chart Section */}
      <ChartSection
        data={filteredData}
        activeMetric={activeMetric}
        onMetricChange={handleMetricChange}
      />

      {/* Detailed Monthly Data Table */}
      <section className="table-card">
        <div className="table-header">
          <h2 className="table-title">月別実績明細</h2>
        </div>

        <div className="table-wrapper">
          <table className="data-table">
            <thead>
              <tr>
                <th className="th-cell">対象月</th>
                <th className="th-cell" style={{ textAlign: 'right' }}>売上実績</th>
                <th className="th-cell" style={{ textAlign: 'right' }}>目標売上</th>
                <th className="th-cell" style={{ textAlign: 'right' }}>達成率</th>
                <th className="th-cell" style={{ textAlign: 'right' }}>来客数</th>
                <th className="th-cell" style={{ textAlign: 'right' }}>客単価</th>
                <th className="th-cell" style={{ textAlign: 'right' }}>売上前月比</th>
              </tr>
            </thead>
            <tbody>
              {filteredData.map((item, index) => {
                const prevItem = index > 0 ? filteredData[index - 1] : null;
                const achievementRate =
                  item.targetSales > 0 ? (item.sales / item.targetSales) * 100 : 0;
                const salesDiff =
                  prevItem && prevItem.sales > 0
                    ? ((item.sales - prevItem.sales) / prevItem.sales) * 100
                    : null;

                const isAchievementHigh = achievementRate >= 100;

                return (
                  <tr key={item.month}>
                    <td className="td-cell" style={{ fontWeight: 500 }}>
                      {item.month}
                    </td>
                    <td className="td-cell td-num">¥{item.sales.toLocaleString()}</td>
                    <td className="td-cell td-num" style={{ color: 'var(--text-muted)' }}>
                      ¥{item.targetSales.toLocaleString()}
                    </td>
                    <td
                      className={`td-cell td-num ${
                        isAchievementHigh ? 'text-up' : 'text-down'
                      }`}
                    >
                      {achievementRate.toFixed(1)}%
                    </td>
                    <td className="td-cell td-num">{item.customers.toLocaleString()}人</td>
                    <td className="td-cell td-num">¥{item.avgSpend.toLocaleString()}</td>
                    <td className="td-cell td-num">
                      {salesDiff !== null ? (
                        <span className={salesDiff >= 0 ? 'text-up' : 'text-down'}>
                          {salesDiff >= 0 ? '+' : ''}
                          {salesDiff.toFixed(1)}%
                        </span>
                      ) : (
                        <span style={{ color: 'var(--text-light)' }}>-</span>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </section>
    </main>
  );
};

export default App;
